}

local M = setmetatable({}, {
    __index = function(self, name)
        local symbol = _symbols[name]
        if symbol == nil then
            return nil
        end
        local value = C[symbol]()
        if _wstring[name] then
            value = _ws_to_str(value)
        end
        rawset(self, name, value)
        return value
    end,
})

return M
